import React, { useEffect, useState } from 'react';
import api from '../api';
import {
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer,
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
} from 'recharts';
import './Dashboard.css';

const COLORS_MAP = {
  backlog:    { bg: '#f3e8ff', border: '#d8b4fe', text: '#7c3aed', dark: '#5b21b6' },
  todo:       { bg: '#fff7ed', border: '#fed7aa', text: '#ea580c', dark: '#9a3412' },
  inProgress: { bg: '#eff6ff', border: '#bfdbfe', text: '#2563eb', dark: '#1e3a8a' },
  done:       { bg: '#f0fdf4', border: '#bbf7d0', text: '#16a34a', dark: '#14532d' },
  projects:   { bg: '#eef2ff', border: '#c7d2fe', text: '#4f46e5', dark: '#312e81' },
  features:   { bg: '#ecfdf5', border: '#a7f3d0', text: '#059669', dark: '#064e3b' },
  bugs:       { bg: '#fff1f2', border: '#fecdd3', text: '#e11d48', dark: '#9f1239' },
};
const PIE_COLORS = ['#6366f1', '#f59e0b', '#10b981', '#f43f5e', '#3b82f6', '#8b5cf6'];

const StatCard = ({ icon, label, value, sublabel, colors }) => (
  <div className="dash-stat-card" style={{
    background: colors.bg,
    border: `1px solid ${colors.border}`,
    borderLeft: `4px solid ${colors.text}`,
  }}>
    <div className="dash-stat-icon" style={{ color: colors.text }}>{icon}</div>
    <div className="dash-stat-body">
      <div className="dash-stat-value" style={{ color: colors.dark }}>{value}</div>
      <div className="dash-stat-label" style={{ color: colors.text }}>{label}</div>
      {sublabel && <div className="dash-stat-sub" style={{ color: colors.text }}>{sublabel}</div>}
    </div>
  </div>
);

// Get lowercase status string from task — handles 'decription' typo in DB
const getStatusStr = (item) => {
  const obj = item.taskStatus || item.status;
  if (!obj) return '';
  if (typeof obj === 'string') return obj.trim().toLowerCase();
  return (obj.decription || obj.description || obj.name || '').trim().toLowerCase();
};

const getStatusLabel = (item) => {
  const obj = item.taskStatus || item.status;
  if (!obj) return 'Unknown';
  if (typeof obj === 'string') return obj;
  return obj.decription || obj.description || obj.name || 'Unknown';
};

// Check if sprint status == "Active" (case-insensitive)
const isActiveSprint = (task) => {
  const s = (task.sprint?.status || '').trim().toLowerCase();
  return s === 'active';
};

// Status bucket logic — single source of truth
const getTaskBucket = (task) => {
  const isUnassigned = !task.user?.id;
  if (isUnassigned) return 'backlog';

  const statusStr = getStatusStr(task);

  if (
    statusStr === '' ||
    statusStr.includes('todo') ||
    statusStr.includes('to do') ||
    statusStr.includes('open') ||
    statusStr.includes('new') ||
    statusStr.includes('assigned') ||
    statusStr.includes('backlog')
  ) return 'todo';

  if (
    statusStr.includes('in progress') ||
    statusStr.includes('inprogress') ||
    statusStr.includes('progress') ||
    statusStr.includes('working') ||
    statusStr.includes('started')
  ) return 'inProgress';

  if (
    statusStr.includes('done') ||
    statusStr.includes('completed') ||
    statusStr.includes('closed') ||
    statusStr.includes('resolved') ||
    statusStr.includes('fixed')
  ) {
    // ✅ Done ONLY counts if task is in an ACTIVE sprint
    return isActiveSprint(task) ? 'done' : null;
  }

  return null; // review/other — not counted
};

const Dashboard = () => {
  const [counts, setCounts]           = useState({ projects: 0, features: 0, bugs: 0 });
  const [taskBuckets, setTaskBuckets] = useState({ backlog: 0, todo: 0, inProgress: 0, done: 0 });
  const [pieData, setPieData]         = useState([]);
  const [barData, setBarData]         = useState([]);
  const [userProfile, setUserProfile] = useState(null);
  const [recentTasks, setRecentTasks] = useState([]);
  const [loading, setLoading]         = useState(true);

  useEffect(() => { fetchStats(); }, []);

  const fetchStats = async () => {
    setLoading(true);
    try {
      // 1. Profile
      const profileRes = await api.get('/user/profile', { withCredentials: true });
      const user = profileRes.data;
      setUserProfile(user);
      const isAdmin = user?.role?.description === 'Admin';

      // 2. Projects & Features
      const [projRes, featRes] = await Promise.all([
        api.get('/projects', { withCredentials: true }),
        api.get('/features', { withCredentials: true }),
      ]);

      // 3. Fetch all tasks
      //    Admin  → /view-tasks?page=0&size=1000 returns { content:[...], ... }
      //    Others → /user/tasks returns flat array (assigned-to-me + unassigned)
      let allTasks = [];
      let bugsCount = 0;

      if (isAdmin) {
        try {
          const res = await api.get('/view-tasks?page=0&size=1000', { withCredentials: true });
          // Handle both paginated {content:[]} and plain []
          allTasks = Array.isArray(res.data)
            ? res.data
            : (res.data?.content || []);
        } catch (e) {
          console.error('Admin tasks fetch error:', e);
        }
        try {
          const bugsRes = await api.get('/view-bugs', { withCredentials: true });
          bugsCount = (bugsRes.data || []).length;
        } catch (e) {}
      } else {
        try {
          const res = await api.get('/user/tasks', { withCredentials: true });
          allTasks = res.data || [];
        } catch (e) {}
        try {
          const bugsRes = await api.get('/user/bugs', { withCredentials: true });
          bugsCount = (bugsRes.data || []).length;
        } catch (e) {}
      }

      setCounts({
        projects: projRes.data.length,
        features: featRes.data.length,
        bugs: bugsCount,
      });

      // 4. Bucket tasks using strict conditions
      let backlog = 0, todo = 0, inProgress = 0, done = 0;
      const statusMap = {};

      allTasks.forEach(task => {
        // Pie chart — show ALL status labels
        const label = getStatusLabel(task);
        statusMap[label] = (statusMap[label] || 0) + 1;

        // Bucket counting
        const bucket = getTaskBucket(task);
        if (bucket === 'backlog')    backlog++;
        else if (bucket === 'todo')       todo++;
        else if (bucket === 'inProgress') inProgress++;
        else if (bucket === 'done')       done++;
      });

      setPieData(Object.keys(statusMap).map(k => ({ name: k, value: statusMap[k] })));
      setBarData([
        { name: 'Backlog',     count: backlog,    fill: '#a78bfa' },
        { name: 'To Do',       count: todo,       fill: '#fb923c' },
        { name: 'In Progress', count: inProgress, fill: '#60a5fa' },
        { name: 'Done',        count: done,       fill: '#34d399' },
      ]);
      setTaskBuckets({ backlog, todo, inProgress, done });

      // 5. Recent 5 tasks — newest first
      const sorted = [...allTasks].sort((a, b) =>
        String(b.createdDate || '').localeCompare(String(a.createdDate || ''))
      ).slice(0, 5);
      setRecentTasks(sorted);

    } catch (err) {
      console.error('Dashboard error:', err);
    }
    setLoading(false);
  };

  const isAdminUser = userProfile?.role?.description === 'Admin';
  const userName    = userProfile?.preffered_name || userProfile?.name || 'User';

  if (loading) {
    return (
      <div className="dashboard-container">
        <div className="dash-loading">
          <div className="dash-spinner" />
          <p>Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">

      {/* ── Header ── */}
      <div className="dash-header">
        <div>
          <h2 className="dash-title">📊 Dashboard</h2>
          <p className="dash-subtitle">
            Welcome back, <strong>{userName}</strong>! Here's your overview.
          </p>
        </div>
      </div>

      {/* ── Overview ── */}
      <div className="dash-section-label">Overview</div>
      <div className="dash-stats-row">
        <StatCard icon="📁" label="Projects" value={counts.projects} colors={COLORS_MAP.projects} />
        <StatCard icon="🧩" label="Features" value={counts.features} colors={COLORS_MAP.features} />
        <StatCard icon="🐛" label="Bugs"     value={counts.bugs}
          sublabel={isAdminUser ? 'Total in system' : 'Assigned to me'}
          colors={COLORS_MAP.bugs} />
      </div>

      {/* ── Task Buckets ── */}
      <div className="dash-section-label">Task Status Breakdown</div>
      <div className="dash-stats-row">
        <StatCard
          icon="📋" label="Backlog" value={taskBuckets.backlog}
          sublabel="Unassigned tasks"
          colors={COLORS_MAP.backlog}
        />
        <StatCard
          icon="📝" label="To Do" value={taskBuckets.todo}
          sublabel="Assigned, not started"
          colors={COLORS_MAP.todo}
        />
        <StatCard
          icon="🚀" label="In Progress" value={taskBuckets.inProgress}
          sublabel="Currently active"
          colors={COLORS_MAP.inProgress}
        />
        <StatCard
          icon="✅" label="Done" value={taskBuckets.done}
          sublabel="Active sprint only"
          colors={COLORS_MAP.done}
        />
      </div>

      {/* ── Charts ── */}
      <div className="dash-section-label">Analytics</div>
      <div className="dash-charts-row">

        <div className="dash-chart-box">
          <h4 className="dash-chart-title">Task Count by Status</h4>
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={barData} margin={{ top: 10, right: 20, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="name" tick={{ fontSize: 13 }} />
              <YAxis allowDecimals={false} tick={{ fontSize: 12 }} />
              <Tooltip />
              <Bar dataKey="count" radius={[6, 6, 0, 0]}>
                {barData.map((entry, i) => (
                  <Cell key={`bar-${i}`} fill={entry.fill} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="dash-chart-box">
          <h4 className="dash-chart-title">Tasks by Status (All)</h4>
          {pieData.length === 0 ? (
            <div className="dash-no-data">No task data available</div>
          ) : (
            <ResponsiveContainer width="100%" height={240}>
              <PieChart>
                <Pie data={pieData} dataKey="value" nameKey="name"
                  outerRadius={85} innerRadius={38}
                  label={({ name, value }) => `${name}: ${value}`}
                  labelLine={false}
                >
                  {pieData.map((_, i) => (
                    <Cell key={`pie-${i}`} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>

      </div>

      {/* ── Recent Tasks Table ── */}
      {recentTasks.length > 0 && (
        <>
          <div className="dash-section-label">Recent Tasks</div>
          <div className="dash-table-box">
            <table className="dash-table">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Task Title</th>
                  <th>Assigned To</th>
                  <th>Sprint</th>
                  <th>Sprint Status</th>
                  <th>Task Status</th>
                </tr>
              </thead>
              <tbody>
                {recentTasks.map(task => {
                  const statusStr   = getStatusStr(task);
                  const statusLabel = getStatusLabel(task);
                  const sprintSt    = (task.sprint?.status || '').trim();
                  const isAssigned  = !!task.user?.id;

                  let badgeClass = 'dash-badge-default';
                  if (!isAssigned) badgeClass = 'dash-badge-backlog';
                  else if (statusStr.includes('done') || statusStr.includes('completed') || statusStr.includes('closed')) badgeClass = 'dash-badge-done';
                  else if (statusStr.includes('progress') || statusStr.includes('active')) badgeClass = 'dash-badge-inprogress';
                  else if (statusStr.includes('todo') || statusStr.includes('open') || statusStr.includes('new')) badgeClass = 'dash-badge-todo';

                  let sprintBadgeClass = 'dash-badge-default';
                  if (sprintSt.toLowerCase() === 'active') sprintBadgeClass = 'dash-badge-inprogress';
                  else if (sprintSt.toLowerCase() === 'completed' || sprintSt.toLowerCase() === 'closed') sprintBadgeClass = 'dash-badge-done';

                  return (
                    <tr key={task.id}>
                      <td>{task.id}</td>
                      <td className="dash-task-title">{task.userstory || '-'}</td>
                      <td>
                        {isAssigned
                          ? (task.user?.preffered_name || task.user?.name || task.user?.username || '-')
                          : <span className="dash-badge dash-badge-backlog">Unassigned</span>
                        }
                      </td>
                      <td>{task.sprint?.name || '-'}</td>
                      <td>
                        {task.sprint
                          ? <span className={`dash-badge ${sprintBadgeClass}`}>{sprintSt || '-'}</span>
                          : '-'}
                      </td>
                      <td>
                        <span className={`dash-badge ${badgeClass}`}>
                          {!isAssigned ? 'Backlog' : statusLabel}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </>
      )}

    </div>
  );
};

export default Dashboard;
