import React, { useState, useEffect, useRef, useCallback } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from '../api';
import "./Navbar.css";
import { FaUserCircle, FaCog, FaSignOutAlt, FaSearch, FaTimes } from "react-icons/fa";

const Navbar = ({ collapsed }) => {
  const [activeDropdown, setActiveDropdown] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [user, setUser] = useState(null);

  // ── Universal Search ──
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [showResults, setShowResults] = useState(false);
  const searchRef = useRef(null);
  const debounceTimer = useRef(null);

  useEffect(() => {
    api.get('/user/profile', { withCredentials: true })
      .then(response => setUser(response.data))
      .catch(error => console.error('Error fetching user profile:', error));
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target))
        setActiveDropdown(false);
      if (searchRef.current && !searchRef.current.contains(event.target))
        setShowResults(false);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Debounced universal search
  const handleSearchChange = (e) => {
    const q = e.target.value;
    setSearchQuery(q);

    if (debounceTimer.current) clearTimeout(debounceTimer.current);

    if (!q.trim()) {
      setSearchResults([]);
      setShowResults(false);
      return;
    }

    debounceTimer.current = setTimeout(() => runSearch(q.trim()), 350);
  };

  const runSearch = async (q) => {
    setSearching(true);
    setShowResults(true);
    const ql = q.toLowerCase();
    const results = [];

    // Fetch projects first to map IDs for bugs/tasks
    let projectsList = [];
    try {
      const projRes = await api.get('/projects', { withCredentials: true });
      projectsList = projRes.data || [];
    } catch (e) {}

    const isAdmin = user?.role?.description === 'Admin';

    try {
      // Tasks
      let tasksRes;
      if (isAdmin) {
        tasksRes = await api.get('/view-tasks?page=0&size=1000', { withCredentials: true });
      } else {
        tasksRes = await api.get('/user/tasks', { withCredentials: true });
      }
      
      const tasks = isAdmin ? (Array.isArray(tasksRes.data) ? tasksRes.data : (tasksRes.data?.content || [])) : (tasksRes.data || []);
      tasks.forEach(t => {
        const title = t.userstory || '';
        const id    = String(t.id || '');
        if (
          title.toLowerCase().includes(ql) ||
          id.includes(ql) ||
          (t.description || '').toLowerCase().includes(ql)
        ) {
          const pid = t.feature?.project?.id || t.sprint?.feature?.project?.id || '';
          results.push({
            type: 'Task',
            icon: '📝',
            label: title || `Task #${t.id}`,
            sub: `#${t.id} · ${t.taskStatus?.decription || t.taskStatus?.description || 'No status'} · ${t.sprint?.name || 'No sprint'}`,
            landingRoute: `/task${pid ? `?project=${pid}` : ''}`,
            route: `/task/${t.id}`,
            color: '#2563eb',
          });
        }
      });
    } catch (e) {}

    try {
      // Bugs
      let bugsRes;
      if (isAdmin) {
        bugsRes = await api.get('/view-bugs', { withCredentials: true });
      } else {
        bugsRes = await api.get('/user/bugs', { withCredentials: true });
      }

      const bugs = bugsRes.data || [];
      bugs.forEach(b => {
        const title = b.title || '';
        const id    = String(b.id || '');
        if (
          title.toLowerCase().includes(ql) ||
          id.includes(ql) ||
          (b.description || '').toLowerCase().includes(ql)
        ) {
          const p = projectsList.find(proj => proj.name === b.projectName);
          const pid = p ? p.id : '';
          results.push({
            type: 'Bug',
            icon: '🐛',
            label: title || `Bug #${b.id}`,
            sub: `#${b.id} · ${b.status?.decription || b.status?.description || 'No status'}`,
            landingRoute: `/bugs${pid ? `?project=${pid}` : ''}`,
            route: `/bug/${b.id}`,
            color: '#e11d48',
          });
        }
      });
    } catch (e) {}

    try {
      // Projects
      projectsList.forEach(p => {
        if (
          (p.name || '').toLowerCase().includes(ql) ||
          String(p.id || '').includes(ql) ||
          (p.description || '').toLowerCase().includes(ql)
        ) {
          results.push({
            type: 'Project',
            icon: '📁',
            label: p.name || `Project #${p.id}`,
            sub: `#${p.id}`,
            landingRoute: `/view-projectsByUserId`,
            route: `/view-project/${p.id}`,
            color: '#4f46e5',
          });
        }
      });
    } catch (e) {}

    try {
      // Features
      const featRes = await api.get('/features', { withCredentials: true });
      const features = featRes.data || [];
      features.forEach(f => {
        if (
          (f.name || '').toLowerCase().includes(ql) ||
          String(f.id || '').includes(ql) ||
          (f.description || '').toLowerCase().includes(ql)
        ) {
          const pid = f.project?.id || '';
          results.push({
            type: 'Feature',
            icon: '🧩',
            label: f.name || `Feature #${f.id}`,
            sub: `#${f.id} · ${f.project?.name || ''}`,
            landingRoute: `/view-features${pid ? `?project=${pid}` : ''}`,
            route: `/ViewSprintsByFeatureid/${f.id}`,
            color: '#059669',
          });
        }
      });
    } catch (e) {}

    try {
      // Sprints
      const sprintsRes = await api.get('/sprints', { withCredentials: true });
      const sprints = sprintsRes.data || [];
      sprints.forEach(s => {
        if (
          (s.name || '').toLowerCase().includes(ql) ||
          String(s.id || '').includes(ql) ||
          (s.sprintGoals || '').toLowerCase().includes(ql)
        ) {
          const pid = s.feature?.project?.id || '';
          results.push({
            type: 'Sprint',
            icon: '🏃',
            label: s.name || `Sprint #${s.id}`,
            sub: `#${s.id} · ${s.status || ''} · ${s.feature?.name || ''}`,
            landingRoute: `/manage-sprints${pid ? `?project=${pid}` : ''}`,
            route: `/sprints/overview/${s.id}`,
            color: '#d97706',
          });
        }
      });
    } catch (e) {}

    setSearchResults(results.slice(0, 10)); // max 10 results
    setSearching(false);
  };

  const handleResultClick = (landingRoute, detailRoute) => {
    setShowResults(false);
    setSearchQuery('');
    setSearchResults([]);
    // Step 1: Replace the current history entry (e.g. dashboard) with the
    //         list/landing page — so Back from detail goes to the list, not dashboard.
    navigate(landingRoute, { replace: true });
    // Step 2: Push the specific detail page on top of history.
    navigate(detailRoute);
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setShowResults(false);
  };

  return (
    <nav className={`top-navbar ${collapsed ? 'collapsed' : ''}`}>
      {/* Brand */}
      <div className="navbar-brand">
        <a
          href="https://www.winfocus.co.in/"
          target="_blank"
          rel="noopener noreferrer"
          className="company-logo"
          style={{ textDecoration: 'none', color: 'white' }}
        >
          winfocus.co.in
        </a>
      </div>

      {/* ── Universal Search Bar ── */}
      <div className="navbar-search" ref={searchRef}>
        <div className="search-input-wrap">
          <FaSearch className="search-icon-left" />
          <input
            type="text"
            className="search-input"
            placeholder="Search tasks, bugs, projects, features..."
            value={searchQuery}
            onChange={handleSearchChange}
            onFocus={() => searchQuery.trim() && setShowResults(true)}
          />
          {searchQuery && (
            <button className="search-clear-btn" onClick={clearSearch}>
              <FaTimes />
            </button>
          )}
        </div>

        {/* Dropdown results */}
        {showResults && (
          <div className="search-dropdown">
            {searching ? (
              <div className="search-status">Searching...</div>
            ) : searchResults.length === 0 ? (
              <div className="search-status">No results found for "<strong>{searchQuery}</strong>"</div>
            ) : (
              <>
                <div className="search-results-count">{searchResults.length} result{searchResults.length !== 1 ? 's' : ''}</div>
                {searchResults.map((r, i) => (
                  <div
                    key={i}
                    className="search-result-item"
                    onClick={() => handleResultClick(r.landingRoute, r.route)}
                  >
                    <span className="search-result-icon">{r.icon}</span>
                    <div className="search-result-body">
                      <span className="search-result-label">{r.label}</span>
                      <span className="search-result-sub">{r.sub}</span>
                    </div>
                    <span className="search-result-type" style={{ color: r.color }}>
                      {r.type}
                    </span>
                  </div>
                ))}
              </>
            )}
          </div>
        )}
      </div>

      {/* Profile */}
      {user && (
        <div className="navbar-right" ref={dropdownRef} style={{ display: 'flex', alignItems: 'center' }}>
          <div className="nav-dropdown-container">
            <button
              className="profile-btn"
              onClick={() => setActiveDropdown(!activeDropdown)}
              style={{ borderRadius: '50%', padding: '5px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <FaUserCircle className="profile-icon" size={28} style={{ margin: 0 }} />
            </button>
            {activeDropdown && (
              <div className="nav-dropdown-menu right-aligned" style={{ minWidth: '180px', padding: '8px 0' }}>
                <div style={{ padding: '8px 20px', borderBottom: '1px solid #eaeaea', marginBottom: '4px' }}>
                  <div style={{ display: 'block', fontWeight: 'bold', color: '#333', fontSize: '14px' }}>
                    {user.first_name} {user.last_name}
                  </div>
                  <div style={{ fontSize: '12px', color: '#666' }}>
                    {user.role?.description}
                  </div>
                </div>
                <Link to="/profile" className="dropdown-item" onClick={() => setActiveDropdown(false)}>
                  <FaUserCircle /> Profile
                </Link>
                <Link to="/view-projectsByUserId" className="dropdown-item" onClick={() => setActiveDropdown(false)}>
                  <FaCog /> My Projects
                </Link>
                <hr style={{ border: 'none', borderTop: '1px solid #eee', margin: '4px 0' }} />
                <Link to="/logout" className="dropdown-item logout-link" onClick={() => setActiveDropdown(false)}>
                  <FaSignOutAlt /> Log out
                </Link>
              </div>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
