import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import './Profile.css';

const Profile = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
   api.get('/user/profile', { withCredentials: true })
      .then(response => {
        setUser(response.data);
      })
      .catch(error => {
        console.error('Error fetching user profile:', error);
        setError('Failed to load profile');
      });
  }, []);

  if (error) return <div>{error}</div>;
  if (!user) return <div>Loading profile...</div>;

  return (
    <div className="profile-container">
      <h2 className="profile-heading">👤 User Profile</h2>
      <div className="profile-card">
        <div className="profile-field">
          <label>Full Name</label>
          <p>{user.first_name} {user.last_name}</p>
        </div>
        <div className="profile-field">
          <label>Preferred Name</label>
          <p>{user.preffered_name}</p>
        </div>
        <div className="profile-field">
          <label>Email</label>
          <p>{user.email}</p>
        </div>
        <div className="profile-field">
          <label>Role</label>
          <p>{user.role.description}</p>
        </div>
      </div>
      <div className="btn-container full-width" style={{ marginTop: '20px' }}>
        <button type="button" className="btn-global btn-secondary" onClick={() => navigate(-1)}>Back</button>
      </div>
    </div>
  );
};

export default Profile;
